package com.pandinila.broadband_management.service;
import com.pandinila.broadband_management.entity.*; import com.pandinila.broadband_management.entity.Enums.RiskLevel; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DataGeneratorService { private final CustomerService customers;private final MonitoringService monitoring;private final IncidentService incidents;private final Random random=new Random(); @Value("${broadband.simulation.enabled:true}") boolean enabled;@Value("${broadband.simulation.auto-create-incidents:true}") boolean automatic;
 public DataGeneratorService(CustomerService c,MonitoringService m,IncidentService i){customers=c;monitoring=m;incidents=i;}
 /** Each customer is processed independently so a duplicate incident can never roll back telemetry for every customer. */
 @Scheduled(fixedRate=20000) public void generate(){if(!enabled)return;for(Customer c:customers.all()){try{NetworkMetric m=metric(c);ComplaintPrediction p=monitoring.process(m);if(automatic&&p.getRiskLevel()==RiskLevel.HIGH){try{incidents.createProactive(c.getId());}catch(IllegalStateException ignored){/* Existing active incident: expected and safe to ignore. */}}}catch(Exception ignored){/* A bad customer cycle must not stop the scheduler. */}}}
 private NetworkMetric metric(Customer c){int n=Integer.parseInt(c.getCustomerId().substring(4));double health=n%10<7?1:n%10<9?.62:.28; NetworkMetric m=new NetworkMetric();m.setCustomer(c);m.setDownloadSpeed(Math.max(8,100*health+jitter(12)));m.setUploadSpeed(Math.max(2,30*health+jitter(4)));m.setLatency(Math.max(5,20+(1-health)*150+jitter(10)));m.setPacketLoss(Math.max(0,(1-health)*10+jitter(1.5)));m.setJitter(Math.max(1,4+(1-health)*30+jitter(3)));m.setSignalStrength(-45-(1-health)*45+jitter(3));m.setBandwidthUtilization(Math.min(100,45+(1-health)*45+jitter(8)));m.setUptime(Math.max(80,99-(1-health)*15));m.setDowntime(Math.max(0,(1-health)*55+jitter(4)));m.setConnectionStability(Math.max(5,96-(1-health)*75+jitter(5)));return m;} private double jitter(double range){return (random.nextDouble()-.5)*range;}}
